use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_or_comma(c: char) -> bool {
    ('a' <= c && c <= 'z') || c == ','
}

spec fn output_char(input: char) -> char {
    if input == ',' {
        ' '
    } else {
        input
    }
}

fn solve(s: Vec<char>) -> (result: Vec<char>)
    requires
        s@.len() == 19,
        forall |i: int| 0 <= i < s@.len() ==> is_lowercase_or_comma(s@[i]),
        s@[5] == ',',
        s@[13] == ',',
    ensures
        result@.len() == 20,
        result@[19] == '\n',
        forall |i: int| 0 <= i < 19 ==> result@[i] == output_char(s@[i]),
{
    let mut result_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < s.len()
        invariant
            idx <= 19,
            result_vec@.len() == idx,
            forall |j: int| 0 <= j < idx ==> result_vec@[j] == output_char(s@[j]),
    {
        let c = s[idx];
        let transformed = if c == ',' { ' ' } else { c };
        result_vec.push(transformed);
        idx = idx + 1;
    }
    
    // Append newline character
    result_vec.push('\n');
    
    result_vec
}

}
